#!/usr/bin/env bash
# STATIC MODE ONLY (values-static.yaml). Creates the Secrets PM4ML reads, from local files.
# Nothing here is written to git. Re-run to rotate (then restart the pods:
# kubectl -n "$NS" rollout restart deploy).
#
#   NS=<namespace> TLS_DIR=./tls ./scripts/create-static-secrets.sh
#
# TLS_DIR must contain:
#   hub-ca.pem    hub CA bundle (root + intermediate), from the hub operator
#   client.pem    your client certificate, SIGNED BY THE HUB CA (from your CSR)
#   client.key    its private key (generated by you, never sent anywhere)
#   in-ca.pem     CA that signed the hub's client certificate (to verify callbacks)
#   server.pem    your callback server certificate, signed by YOUR CA,
#                 SAN = the callback host you gave the hub
#   server.key    its private key
#   jws.key       your JWS private key (send only jws.pub to the hub)
# ILP_SECRET defaults to a fresh random value. Keep it stable across restarts:
# transfers quoted under an old secret cannot complete under a new one.
set -euo pipefail
NS="${NS:?set NS}"
TLS_DIR="${TLS_DIR:?set TLS_DIR}"

for f in hub-ca.pem client.pem client.key in-ca.pem server.pem server.key jws.key; do
  [ -s "$TLS_DIR/$f" ] || { echo "missing $TLS_DIR/$f" >&2; exit 1; }
done

# Sanity checks that would otherwise surface as opaque TLS errors.
openssl verify -CAfile "$TLS_DIR/hub-ca.pem" "$TLS_DIR/client.pem" >/dev/null \
  || { echo "client.pem is not signed by hub-ca.pem; the hub edge will refuse it" >&2; exit 1; }
for pair in client server; do
  a=$(openssl x509 -in "$TLS_DIR/$pair.pem" -noout -pubkey | openssl sha256)
  b=$(openssl pkey -in "$TLS_DIR/$pair.key" -pubout | openssl sha256)
  [ "$a" = "$b" ] || { echo "$pair.pem and $pair.key do not match" >&2; exit 1; }
done
# Go/Envoy peers need a trailing newline after END CERTIFICATE.
for f in "$TLS_DIR"/*.pem; do [ -z "$(tail -c1 "$f")" ] || echo >> "$f"; done

ILP_SECRET="${ILP_SECRET:-$(kubectl -n "$NS" get secret pm4ml-runtime -o jsonpath='{.data.ilp-secret}' 2>/dev/null | base64 -d || true)}"
ILP_SECRET="${ILP_SECRET:-$(openssl rand -hex 32)}"

apply() { kubectl -n "$NS" create secret generic "$@" --dry-run=client -o yaml | kubectl -n "$NS" apply -f -; }
apply pm4ml-tls \
  --from-file=hub-ca.pem="$TLS_DIR/hub-ca.pem" \
  --from-file=client.pem="$TLS_DIR/client.pem" \
  --from-file=client.key="$TLS_DIR/client.key" \
  --from-file=in-ca.pem="$TLS_DIR/in-ca.pem" \
  --from-file=server.pem="$TLS_DIR/server.pem" \
  --from-file=server.key="$TLS_DIR/server.key"
apply pm4ml-jws --from-file=jws-signing.key="$TLS_DIR/jws.key"
# Through files, so the values do not show up in the process list.
tmp="$(mktemp -d)"; trap 'rm -rf "$tmp"' EXIT
printf '%s' "$ILP_SECRET" > "$tmp/ilp-secret"
apply pm4ml-runtime --from-file=ilp-secret="$tmp/ilp-secret"
echo "Secrets pm4ml-tls, pm4ml-jws, pm4ml-runtime are in namespace $NS."
